using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 // Live configuration records references, never installs into the source game or Workshop.
 sealed class LauncherComponents {
  internal sealed class Selection {public string Id,SourceRoot;public bool Enabled;}
  internal sealed class State {public int Version=1;public List<Selection> Selections=new List<Selection>();public List<string> Managed=new List<string>();public Dictionary<string,bool> Decisions=new Dictionary<string,bool>();}
  internal sealed class Row {public string Id,Name,SourceRoot,Jar,Package,Sha256,ApprovalStamp,SourceEvidence,Warning="";public bool Enabled,Selected,installationComponent,requiresBuddy;public bool? Decision;public string[] Requires=new string[0],LoadAfter=new string[0],LoadBefore=new string[0],Conflicts=new string[0];}
  internal sealed class Capture {internal Row[] Rows;internal string[] Managed,OrdinaryIds;internal byte[] Ordinary;internal string StateStamp;}
  sealed class OrdinaryState {public int Version=1;public bool Committed;public string TargetHash;public Dictionary<string,string> Sources=new Dictionary<string,string>(StringComparer.Ordinal);}
  readonly LauncherConfiguration context;readonly Version version;readonly string statePath;readonly Action<int,string> progress;
  internal static readonly string[] KnownIds=new[]{"ZombieBuddy","Viewpoint","PZVoxelStudioViewpoint","ShootToThrillMultiplayer","LaoYuTranslationJava","OrangeShootPresentation"}.Concat(ViewpointAddons.All.Select(a=>a.Id)).ToArray();
  internal static bool InstallationComponent(string id){return (id??"").TrimStart('\\')=="ZombieBuddy";}
  internal static string[] Dependencies(string id,IEnumerable<string> declared){return (declared??new string[0]).Concat((id??"").TrimStart('\\')=="PZVoxelStudioViewpoint"?new[]{"Viewpoint","ZombieBuddy"}:new string[0]).Distinct(StringComparer.Ordinal).ToArray();}
  internal LauncherComponents(LauncherConfiguration context,Version version,Action<int,string> progress=null){if(context==null||version==null)throw new ArgumentNullException();this.context=context;this.version=version;this.progress=progress;statePath=Path.Combine(context.ComponentsDirectory,"selection.json");}
  internal Version GameVersion{get{return version;}}
  internal LauncherConfiguration Context{get{return context;}}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152};}
  internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  internal static string HashFile(string file){return HashFile(file,CancellationToken.None);}
  static string HashFile(string file,CancellationToken token){LauncherMaintenance.NoReparse(file);using(var sha=SHA256.Create())using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){var bytes=new byte[65536];int count;while((count=input.Read(bytes,0,bytes.Length))>0){token.ThrowIfCancellationRequested();sha.TransformBlock(bytes,0,count,null,0);}sha.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant();}}
  static string Full(string path){if(string.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path)||path.Any(char.IsControl))throw new IOException("组件来源必须是明确的本地目录。");string full=Path.GetFullPath(path).TrimEnd('\\','/');LauncherMaintenance.NoReparse(full);return full;}
  static string Id(string id){id=(id??"").TrimStart('\\');if(!SaveProfiles.Id(id))throw new IOException("组件 ID 无效。");return id;}
  State Read(){LauncherMaintenance.NoReparse(statePath);if(!File.Exists(statePath))return new State();if(new FileInfo(statePath).Length>2097152)throw new IOException("组件记录过大。");var s=Json().Deserialize<State>(File.ReadAllText(statePath));if(s==null||s.Version!=1||s.Selections==null||s.Decisions==null||s.Managed==null||s.Managed.Count>2000||s.Managed.Any(x=>Id(x)!=x)||s.Selections.Count>2000||s.Selections.Any(x=>x==null||Id(x.Id)!=x.Id||Full(x.SourceRoot)!=x.SourceRoot)||s.Selections.Select(x=>x.Id).Distinct().Count()!=s.Selections.Count)throw new IOException("组件记录无效，请检查所选配置。");return s;}
  internal static void Atomic(string path,byte[] bytes){LauncherMaintenance.NoReparse(path);Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+"."+Guid.NewGuid().ToString("N").Substring(0,8)+".tmp";try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  void Write(Action<State> change,CancellationToken token){if(context.Mode!="launcher")throw new IOException("请在启动器配置中修改组件。");string name="Local\\OrangeComponents-"+Hash(Encoding.UTF8.GetBytes(context.Root.ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("此配置的组件正在修改，请稍后重试。");token.ThrowIfCancellationRequested();var state=Read();change(state);token.ThrowIfCancellationRequested();context.Initialize();Atomic(statePath,Encoding.UTF8.GetBytes(Json().Serialize(state)));}finally{if(held)mutex.ReleaseMutex();}}}
  static string SourceStamp(string root){var files=new[]{Path.Combine(root,"mod.info")}.Concat(Directory.GetDirectories(root).Where(p=>Path.GetFileName(p)=="common"||Regex.IsMatch(Path.GetFileName(p),@"^\d+(\.\d+)*$")).Select(p=>Path.Combine(p,"mod.info"))).Where(File.Exists).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase).ToArray();return Hash(Encoding.UTF8.GetBytes(string.Join("\n",files.Select(p=>{LauncherMaintenance.NoReparse(p);if(new FileInfo(p).Length>262144)throw new IOException("模组元数据过大。");var seen=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in File.ReadAllLines(p)){int at=line.IndexOf('=');if(at<=0)continue;string key=line.Substring(0,at).Trim(),value=line.Substring(at+1).Trim(),prior;if(!Regex.IsMatch(key,@"^(id|require|java.*|ZBVersion.*|versionMin|versionMax)$",RegexOptions.IgnoreCase))continue;if(seen.TryGetValue(key,out prior)&&prior!=value)throw new IOException("模组资料包含不同的重复加载声明："+p+" · "+key);seen[key]=value;}return p+"="+HashFile(p);})))) ;}
  static string ApprovalKey(Row row){return Hash(Encoding.UTF8.GetBytes(row.Id+"\n"+row.SourceRoot.ToUpperInvariant()+"\n"+row.Jar.ToUpperInvariant()+"\n"+row.Package+"\n"+row.Sha256));}
  internal Row Inspect(string sourceRoot,string id,CancellationToken token){token.ThrowIfCancellationRequested();sourceRoot=Full(sourceRoot);id=Id(id);if(!Directory.Exists(sourceRoot))throw new IOException(id+"：来源目录已不存在："+sourceRoot);string sourceEvidence=SourceStamp(sourceRoot);string mods=Path.GetDirectoryName(sourceRoot);if(!Path.GetFileName(mods).Equals("mods",StringComparison.OrdinalIgnoreCase))throw new IOException(id+"：请选择 mods 下的具体模组目录。");
   // Reuse the existing version-aware metadata/JAR resolver with an explicit selected folder.
   var budget=new LaunchReadBudget(16777216,10000);budget.Checkpoint=(file,size)=>token.ThrowIfCancellationRequested();var f=ViewpointAddons.ResolveSource(Path.GetDirectoryName(mods),id,version,budget,sourceRoot);
   foreach(string folder in new[]{sourceRoot}.Concat(Directory.GetDirectories(sourceRoot).Where(p=>Path.GetFileName(p)=="common"||Regex.IsMatch(Path.GetFileName(p),@"^\d+(\.\d+)*$")))){var m=ViewpointAddons.Metadata(Path.Combine(folder,"mod.info"),budget);string declared;if(m.TryGetValue("id",out declared)&&Id(declared)!=id)throw new IOException(id+"：同一目录声明了不同模组身份。");}
   string name,pkg,require;f.Metadata.TryGetValue("name",out name);(f.JavaMetadata??f.Metadata).TryGetValue("javaPkgName",out pkg);f.Metadata.TryGetValue("require",out require);if(f.Jar!=null&&!Regex.IsMatch(pkg??"",@"^[A-Za-z_$][A-Za-z0-9_$]*(\.[A-Za-z_$][A-Za-z0-9_$]*)*$"))throw new IOException(id+"：Java 包名无效。");
   JavaComponents.Versions(version.ToString(),f.Metadata,"versionMin","versionMax",true);JavaComponents.Versions("2.3.4",f.JavaMetadata??f.Metadata,"ZBVersionMin","ZBVersionMax",false);
   if(f.Jar==null&&f.Metadata.Keys.Any(k=>Regex.IsMatch(k,"^javaJarFile[0-9]+$",RegexOptions.IgnoreCase)))throw new IOException(id+"：此模组需要 Buddy 3 的编号 Java 声明；当前独立运行支持 Buddy 2.3.4。");
   var row=new Row{Id=id,Name=name??id,SourceRoot=sourceRoot,Jar=f.Jar,Package=pkg??"",installationComponent=InstallationComponent(id),Requires=Dependencies(id,Edges(f.Metadata,"require")),LoadAfter=Edges(f.Metadata,"loadAfter"),LoadBefore=Edges(f.Metadata,"loadBefore"),Conflicts=Edges(f.Metadata,"incompatible")};row.requiresBuddy=!row.installationComponent&&(f.Jar!=null||row.Requires.Contains("ZombieBuddy"));if(row.requiresBuddy)row.Requires=row.Requires.Concat(new[]{"ZombieBuddy"}).Distinct().ToArray();if(f.Jar!=null){if(new FileInfo(f.Jar).Length>134217728)throw new IOException(id+"：Java 文件超过128MB读取上限。");string beforeHash=HashFile(f.Jar,token);JavaComponents.ValidateJarIdentity(f.Jar,row.Package);row.Sha256=HashFile(f.Jar,token);if(beforeHash!=row.Sha256)throw new IOException(id+"：Java 文件正在更新，请重试。");row.ApprovalStamp=ApprovalKey(row);}if(sourceEvidence!=SourceStamp(sourceRoot))throw new IOException(id+"：模组资料正在更新，请重试。");row.SourceEvidence=sourceEvidence;token.ThrowIfCancellationRequested();return row;
  }
  string OrdinaryStatePath{get{return Path.Combine(Path.GetDirectoryName(context.DefaultModsPath),"ordinary-membership.json");}}
  OrdinaryState ReadOrdinaryState(){LauncherMaintenance.NoReparse(OrdinaryStatePath);if(!File.Exists(OrdinaryStatePath))return new OrdinaryState();if(new FileInfo(OrdinaryStatePath).Length>1048576)throw new IOException("普通模组来源记录过大。");var state=Json().Deserialize<OrdinaryState>(File.ReadAllText(OrdinaryStatePath));if(state==null||state.Version!=1||state.TargetHash==null||!Regex.IsMatch(state.TargetHash,"^[a-f0-9]{64}$")||state.Sources==null||state.Sources.Count>2000||state.Sources.Any(pair=>Id(pair.Key)!=pair.Key||Full(pair.Value)!=pair.Value))throw new IOException("普通模组来源记录无效。");return state;}
  string[] Membership(State state,byte[] bytes,OrdinaryState ordinary){var ids=SaveProfiles.DefaultMods(bytes).Where(id=>!InstallationComponent(id)&&Id(id)!=PresentationBridge.Id).ToList();bool authoritative=ordinary.TargetHash!=null&&(ordinary.Committed||ordinary.TargetHash==Hash(bytes??new byte[0]));if(!authoritative)foreach(var selected in state.Selections.Where(s=>s.Enabled&&!InstallationComponent(s.Id)&&s.Id!=PresentationBridge.Id))if(!ids.Any(id=>Id(id)==selected.Id))ids.Add(selected.Id);return ids.ToArray();}
  Row InspectRow(State state,string root,string id,CancellationToken token){Row row;try{row=Inspect(root,id,token);bool decision;if(row.Jar!=null&&state.Decisions.TryGetValue(ApprovalKey(row),out decision))row.Decision=decision;}catch(OperationCanceledException){throw;}catch(Exception error){row=new Row{Id=id,Name=id,SourceRoot=root,Warning=error.Message,installationComponent=InstallationComponent(id)};}row.Selected=true;return row;}
  Row[] Rows(State state,CancellationToken token,string[] ordinaryOverride=null){
   var ordinary=ReadOrdinaryState();var rows=new List<Row>();foreach(var selected in state.Selections.Where(s=>InstallationComponent(s.Id))){var row=InspectRow(state,selected.SourceRoot,selected.Id,token);row.Enabled=selected.Enabled;rows.Add(row);}
   var ids=ordinaryOverride??Membership(state,context.DefaultModsBytes(),ordinary);var pending=new Queue<string>(ids.Select(Id));var seen=new HashSet<string>(StringComparer.Ordinal);SaveProfiles.PreflightCatalog catalog=null;
   while(pending.Count>0){token.ThrowIfCancellationRequested();string id=pending.Dequeue();if(!seen.Add(id)||InstallationComponent(id)||id==PresentationBridge.Id||id=="Viewpoint"&&!ids.Any(value=>Id(value)==id))continue;string root;var legacy=state.Selections.SingleOrDefault(s=>s.Id==id);if(!ordinary.Sources.TryGetValue(id,out root))root=legacy==null?null:legacy.SourceRoot;
    if(root==null){if(catalog==null){var source=new Engine(context.Game,context.User,context.DataDirectory,true,null,null,false){ModCatalogVersion=version};var budget=new LaunchReadBudget(67108864,100000);budget.Checkpoint=(file,size)=>token.ThrowIfCancellationRequested();catalog=SaveProfiles.SnapshotEntries(source,ids,new List<string>(),budget);if(budget.Incomplete)throw new IOException("普通模组来源未能完整读取。");}var matches=catalog.Candidates.Where(c=>c.Id==id).Select(c=>c.Root).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(matches.Length==0)continue;if(matches.Length!=1){rows.Add(new Row{Id=id,Name=id,Enabled=true,Selected=true,Warning=id+"：模组来源不唯一，请核对同名目录。"});continue;}root=matches[0];}
    var item=InspectRow(state,root,id,token);item.Enabled=true;foreach(string dependency in item.Requires)if(!InstallationComponent(dependency))pending.Enqueue(dependency);if(item.Jar!=null||legacy!=null||ordinary.Sources.ContainsKey(id)||item.Warning!="")rows.Add(item);
   }return rows.ToArray();
  }
  internal Row[] List(CancellationToken token){token.ThrowIfCancellationRequested();return Rows(Read(),token);}
  internal Row[] Installations(CancellationToken token){var state=Read();return state.Selections.Where(s=>InstallationComponent(s.Id)).Select(s=>{var row=InspectRow(state,s.SourceRoot,s.Id,token);row.Enabled=s.Enabled;return row;}).ToArray();}
  internal Dictionary<string,string> SourceHints(){var hints=new Dictionary<string,string>(ReadOrdinaryState().Sources,StringComparer.Ordinal);foreach(var selection in Read().Selections)if(!hints.ContainsKey(selection.Id))hints[selection.Id]=selection.SourceRoot;return hints;}
  internal bool RegisteredSupport(string id){id=Id(id);return Read().Selections.Any(row=>row.Id==id)||ReadOrdinaryState().Sources.ContainsKey(id)||OrdinaryIds().Any(value=>Id(value)==id);}
  // Called while OwnedSupportInstallations holds this profile's component and ordinary leases.
  internal void UnregisterSupport(string id,CancellationToken token){id=Id(id);token.ThrowIfCancellationRequested();if(!InstallationComponent(id))SaveOrdinaryCore(OrdinaryIds(token).Where(value=>Id(value)!=id).ToArray(),token,null,null);if(Read().Selections.Any(row=>row.Id==id))Write(state=>state.Selections.RemoveAll(row=>row.Id==id),token);var metadata=ReadOrdinaryState();if(metadata.Sources.Remove(id)){token.ThrowIfCancellationRequested();Atomic(OrdinaryStatePath,Encoding.UTF8.GetBytes(Json().Serialize(metadata)));}}
  static string[] Edges(Dictionary<string,string> metadata,string key){string value;metadata.TryGetValue(key,out value);return (value??"").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(x=>Id(x.Trim())).Distinct().ToArray();}
  internal string[] ManagedIds(){return new[]{"ZombieBuddy"};}
  internal void Select(string sourceRoot,string id,bool enabled,CancellationToken token){var row=Inspect(sourceRoot,id,token);if(!InstallationComponent(row.Id)){var ids=OrdinaryIds(token).ToList();if(enabled){if(!ids.Any(value=>Id(value)==row.Id))ids.Add(row.Id);}else ids.RemoveAll(value=>Id(value)==row.Id);SaveOrdinaryCore(ids.ToArray(),token,row.Id,row.SourceRoot);return;}Write(s=>{if(!s.Managed.Contains(row.Id))s.Managed.Add(row.Id);var prior=s.Selections.Find(x=>x.Id==row.Id);if(prior==null)s.Selections.Add(new Selection{Id=row.Id,SourceRoot=row.SourceRoot,Enabled=enabled});else{prior.SourceRoot=row.SourceRoot;prior.Enabled=enabled;}},token);}
  internal void SetEnabled(string id,bool enabled,CancellationToken token,string expectedSource=null){id=Id(id);if(!InstallationComponent(id)){var current=List(token).SingleOrDefault(row=>row.Id==id);if(expectedSource!=null&&(current==null||!VersionLibrary.Same(current.SourceRoot,Full(expectedSource))))throw new IOException(id+"：普通模组来源已变化。");var ids=OrdinaryIds(token).ToList();if(enabled){if(!ids.Any(value=>Id(value)==id))ids.Add(id);}else ids.RemoveAll(value=>Id(value)==id);SaveOrdinaryCore(ids.ToArray(),token,id,current==null?null:current.SourceRoot);return;}Write(s=>{var selected=s.Selections.SingleOrDefault(x=>x.Id==id);if(selected==null)throw new IOException(id+"：请先选择组件来源。");if(expectedSource!=null&&!VersionLibrary.Same(selected.SourceRoot,Full(expectedSource)))throw new IOException(id+"：此来源不是当前配置所选组件。");if(enabled)Inspect(selected.SourceRoot,id,token);selected.Enabled=enabled;},token);}
  internal void Uninstall(string id,CancellationToken token,string expectedSource=null){id=Id(id);if(!InstallationComponent(id)){SetEnabled(id,false,token,expectedSource);return;}Write(s=>{if(expectedSource!=null&&!s.Selections.Any(x=>x.Id==id&&VersionLibrary.Same(x.SourceRoot,Full(expectedSource))))throw new IOException(id+"：此来源不是当前配置所选组件。");s.Selections.RemoveAll(x=>x.Id==id);},token);}
  internal void Decide(string id,string expectedStamp,bool allow,CancellationToken token,string[] ordinaryOverride=null,Action requireCurrent=null){id=Id(id);Write(s=>{if(requireCurrent!=null)requireCurrent();var row=Rows(s,token,ordinaryOverride).SingleOrDefault(x=>x.Id==id);if(row==null||!row.Enabled||row.Jar==null||row.Warning!=""||row.ApprovalStamp!=expectedStamp)throw new IOException(id+"：Java 文件或选择已变化，请刷新后授权。");s.Decisions[ApprovalKey(row)]=allow;},token);}
  string SelectionStamp(State state){var ordinary=ReadOrdinaryState();return Hash(Encoding.UTF8.GetBytes(Json().Serialize(new{state.Version,state.Selections,state.Managed,decisions=state.Decisions.OrderBy(pair=>pair.Key,StringComparer.Ordinal).ToArray(),ordinary=new{ordinary.Version,ordinary.Committed,ordinary.TargetHash,sources=ordinary.Sources.OrderBy(pair=>pair.Key,StringComparer.Ordinal).ToArray()}})));}
  internal Capture CaptureCurrent(CancellationToken token){return CaptureCurrent(token,null);}
  internal Capture CaptureCurrent(CancellationToken token,string[] ordinaryOverride){var state=Read();byte[] bytes=context.DefaultModsBytes();var capture=new Capture{StateStamp=SelectionStamp(state),Rows=Rows(state,token,ordinaryOverride),Managed=ManagedIds(),Ordinary=bytes,OrdinaryIds=ordinaryOverride??Membership(state,bytes,ReadOrdinaryState())};RequireCurrent(capture);return capture;}
  internal void RequireCurrent(Capture capture){string currentState=SelectionStamp(Read()),beforeHash=Hash(capture.Ordinary??new byte[0]),currentHash=Hash(context.DefaultModsBytes());if(currentState!=capture.StateStamp||beforeHash!=currentHash){var error=new IOException("启动配置已变化，请重新启动。");error.Data["selectionBefore"]=capture.StateStamp;error.Data["selectionNow"]=currentState;error.Data["ordinaryBefore"]=beforeHash;error.Data["ordinaryNow"]=currentHash;throw error;}foreach(var row in capture.Rows.Where(x=>x.Enabled&&x.Warning==""))if(row.SourceEvidence!=SourceStamp(row.SourceRoot))throw new IOException(row.Name+"：模组资料已更新，请重试。");}
  internal ModConfigurations.SortResult PlanEnabled(SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token){return PlanEnabled(CaptureCurrent(token),ordinaryCatalog,token,null);}
  internal ModConfigurations.SortResult PlanEnabled(Capture capture,SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token,string[] ordinaryOverride){var rows=capture.Rows.Where(x=>x.Enabled).ToArray();var managed=capture.Managed;string[] ordinary=(ordinaryOverride??capture.OrdinaryIds??SaveProfiles.DefaultMods(capture.Ordinary)).Where(x=>!managed.Contains(Id(x))).ToArray();var entries=(ordinaryCatalog??new SaveProfiles.Entry[0]).Where(x=>!managed.Contains(Id(x.id))&&!rows.Any(row=>row.Id==Id(x.id))).ToList();foreach(var row in rows){if(row.Warning!="")throw new IOException(row.Warning);entries.Add(new SaveProfiles.Entry{id=row.Id,requires=row.Requires,loadAfter=row.LoadAfter,loadBefore=row.LoadBefore,conflicts=row.Conflicts});}var requested=rows.Where(row=>row.installationComponent).Select(x=>x.Id).Concat(ordinary).Concat(rows.Select(row=>row.Id)).Distinct().ToList();var queue=new Queue<string>(requested);var visited=new HashSet<string>();while(queue.Count>0){token.ThrowIfCancellationRequested();string id=queue.Dequeue();if(!visited.Add(id))continue;var found=entries.Where(e=>Id(e.id)==Id(id)).ToArray();if(found.Length!=1)continue;foreach(string raw in found[0].requires??new string[0]){string dependency=Id(raw);var sources=entries.Where(e=>Id(e.id)==dependency).ToArray();if(sources.Length!=1||InstallationComponent(dependency)&&!rows.Any(row=>row.Id==dependency)||dependency=="Viewpoint"&&!ordinary.Any(value=>Id(value)==dependency))throw new IOException(id+"：依赖 "+dependency+" 尚无唯一可用的当前来源。");if(!requested.Any(value=>Id(value)==dependency))requested.Add(dependency);queue.Enqueue(dependency);}}return ModConfigurations.Order(requested.ToArray(),entries,new List<string>(),new HashSet<string>(ordinary));}
  internal string[] OrdinaryIds(CancellationToken token=default(CancellationToken)){token.ThrowIfCancellationRequested();return Membership(Read(),context.DefaultModsBytes(),ReadOrdinaryState());}
  internal void SaveOrdinary(string[] ids,CancellationToken token){SaveOrdinaryCore(ids,token,null,null);}
  void SaveOrdinaryCore(string[] ids,CancellationToken token,string sourceId,string sourceRoot){if(context.Mode!="launcher")throw new IOException("请在启动器配置中修改普通模组。");if(ids==null||ids.Length>2000||ids.Any(x=>!SaveProfiles.Id(x)||InstallationComponent(x)||Id(x)==PresentationBridge.Id)||ids.Distinct().Count()!=ids.Length)throw new IOException("普通模组清单无效或含独立安装框架。");string name="Local\\OrangeOrdinary-"+Hash(Encoding.UTF8.GetBytes(context.Root.ToUpperInvariant()));using(var mutex=new Mutex(false,name)){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("此配置的普通模组清单正在修改，请稍后重试。");token.ThrowIfCancellationRequested();byte[] before=context.DefaultModsBytes();var selected=Read();var metadata=ReadOrdinaryState();if(Membership(selected,before,metadata).SequenceEqual(ids)&&sourceRoot==null)return;foreach(var legacy in selected.Selections.Where(row=>!InstallationComponent(row.Id)))if(!metadata.Sources.ContainsKey(legacy.Id))metadata.Sources[legacy.Id]=legacy.SourceRoot;if(sourceRoot!=null)metadata.Sources[Id(sourceId)]=Full(sourceRoot);byte[] output=SaveProfiles.DefaultMods(before).SequenceEqual(ids)?before:SaveProfiles.ReplaceDefaultMods(before,ids);metadata.TargetHash=Hash(output);metadata.Committed=output.SequenceEqual(before);token.ThrowIfCancellationRequested();context.Initialize();token.ThrowIfCancellationRequested();Atomic(OrdinaryStatePath,Encoding.UTF8.GetBytes(Json().Serialize(metadata)));if(!output.SequenceEqual(before)){token.ThrowIfCancellationRequested();Atomic(context.DefaultModsPath,output);}metadata.Committed=true;Atomic(OrdinaryStatePath,Encoding.UTF8.GetBytes(Json().Serialize(metadata)));}finally{if(held)mutex.ReleaseMutex();}}}

 }
